INSERT INTO users (display_name, email, avatar_path, bio, location_text, badge_label, joined_at, rating, swaps_completed, is_verified) VALUES
('Sarah Miller', 'sarah@example.com', '/public/images/users/sarah-miller.png', 'Avid reader and collector of vintage editions. I love swapping books that have moved me for new stories. Always looking for classic literature, design systems, and contemporary poetry. All my items are kept in smoke-free environments.', 'Seattle, WA', 'Power User', '2023-10-01', 4.9, 12, 1),
('Alex Record', 'alex@example.com', '/public/images/users/alex-record.png', 'Collector of records, cameras, and music history books. Happy to trade fairly and always meet in public places.', 'Portland, OR', 'Top Swapper', '2024-01-05', 4.8, 8, 1),
('Marcus Chen', 'marcus@example.com', '/public/images/users/marcus-chen.png', 'Fantasy fan, manga reader, and collector of beautifully illustrated editions.', 'Manchester, UK', 'Verified Swapper', '2024-02-12', 4.8, 15, 1),
('Elena Rodriguez', 'elena@example.com', '/public/images/users/elena-rodriguez.png', 'I enjoy jazz records, modern poetry, and community swaps that feel safe and respectful.', 'Madrid, ES', 'Trusted Member', '2023-11-20', 4.7, 4, 0),
('David Kim', 'david@example.com', '/public/images/users/david-kim.png', 'Designer, book lover, and careful collector of minimal editions and rare print finds.', 'Berlin, DE','Top Contributor', '2023-12-10', 4.9, 22, 1);
