('Dune', 'Frank Herbert', 'book', 'Fair Condition', 'Sci-fi staple in good reading condition with bright cover art.', '/public/images/items/dune.jpg', NULL, NULL, NULL, 'New York, US', 3, 1, DATE_SUB(NOW(), INTERVAL 5 DAY)),
('Abbey Road', 'The Beatles', 'record', 'Good Condition', 'Classic album with strong playback quality and a sharp sleeve.', '/public/images/items/abbey-road.jpg', NULL, NULL, NULL, 'Liverpool, UK', 4, 1, DATE_SUB(NOW(), INTERVAL 6 DAY)),
