('American Gods', 'Neil Gaiman', 'book', 'Good', 'Dark fantasy edition with excellent cover presentation.', '/public/images/items/american-gods.jpg', NULL, NULL, NULL, 'Leeds, UK', 3, 0, DATE_SUB(NOW(), INTERVAL 10 DAY)),
