('Modern Poetry Vol 1', 'Jahan Ramazani', 'book', 'Good', 'Soft neutral-toned poetry collection, clean and giftable.', '/public/images/items/modern-poetry-vol-1.jpg', NULL, NULL, NULL, 'Madrid, ES', 4, 0, DATE_SUB(NOW(), INTERVAL 16 DAY)),
